insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A2-018', 'A2', 'story', 'small_talk', 9, 'Що мені подобається в Хорватії', 'Što mi se sviđa u Hrvatskoj',
        'Živim u Hrvatskoj dvije godine i često me pitaju što mi se ovdje najviše sviđa. Prvo, more! Nikad prije nisam vidjela tako čisto i plavo more. Drugo, ljudi nikamo ne žure. Kava s prijateljima može trajati dva sata i to je normalno. Treće, hrana je jednostavna, ali odlična: riba, maslinovo ulje, svježe povrće. Naravno, nije sve savršeno. Papirologija je ponekad spora, a ljeti je previše turista. Ali kad sve usporedim, mislim da sam imala sreće što sam došla baš ovdje.',
        'Я живу в Хорватії два роки, і мене часто питають, що мені тут найбільше подобається. По-перше, море! Ніколи раніше я не бачила такого чистого й синього моря. По-друге, люди нікуди не поспішають. Кава з друзями може тривати дві години, і це нормально. По-третє, їжа проста, але чудова: риба, оливкова олія, свіжі овочі. Звісно, не все ідеально. Паперова тяганина іноді повільна, а влітку забагато туристів. Але коли я все порівнюю, думаю, мені пощастило, що я приїхала саме сюди.',
