insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A2-019', 'A2', 'news', 'cafe_restaurant', 10, 'Фестиваль у Загребі', 'Festival u Zagrebu',
        'Ovog vikenda u Zagrebu se održava Festival hrane i vina. Na Trgu bana Jelačića bit će više od pedeset štandova s domaćim proizvodima iz cijele Hrvatske. Posjetitelji će moći probati sireve, pršut, med i vina iz Istre, Slavonije i Dalmacije. Za djecu su organizirane radionice i predstave. Festival je otvoren od petka do nedjelje, od 10 do 22 sata, a ulaz je besplatan. Organizatori očekuju više od dvadeset tisuća posjetitelja. Ako bude padala kiša, program će se preseliti na tržnicu Dolac.',
        'Цими вихідними в Загребі проходить Фестиваль їжі та вина. На площі бана Єлачича буде понад п’ятдесят наметів із домашніми продуктами з усієї Хорватії. Відвідувачі зможуть скуштувати сири, пршут, мед і вина з Істрії, Славонії та Далмації. Для дітей підготували майстер-класи й вистави. Фестиваль відкритий із п’ятниці до неділі, з 10 до 22 години, вхід безкоштовний. Організатори очікують понад двадцять тисяч відвідувачів. Якщо йтиме дощ, програму перенесуть на ринок Долац.',
